# WAR ARENA - Live GMGN CLI Executor - Installer
# Run from project root:  powershell -ExecutionPolicy Bypass -File .\install-gmgn-live.ps1
# Additive only. The ONLY missing piece for live GMGN: a real CliExecutor that spawns gmgn-cli.
# Files Base64-encoded (no here-strings, no BOM).
$ErrorActionPreference = "Stop"
Write-Host "WAR - Live GMGN CLI Executor installer" -ForegroundColor Cyan
function Write-B64([string]$Path, [string]$B64){
  $dir = Split-Path -Parent $Path
  if ($dir -and -not (Test-Path $dir)) { New-Item -ItemType Directory -Force -Path $dir | Out-Null }
  [System.IO.File]::WriteAllBytes($Path, [System.Convert]::FromBase64String($B64))
  Write-Host "  wrote $Path" -ForegroundColor DarkGray
}

Write-B64 "src/integration/GmgnCliExecutor.ts" ""
Write-B64 "tests/unit/gmgnCliExecutor.test.ts" ""

# --- Ensure GmgnCliExecutor is exported from integration barrel (idempotent) ---
$bar = "src/integration/index.ts"
if (Test-Path $bar) {
  $c = Get-Content $bar -Raw
  if ($c -notmatch "GmgnCliExecutor") {
    $enc = New-Object System.Text.UTF8Encoding($false)
    $line = 'export * from "./GmgnCliExecutor.js";'
    $c = $c.TrimEnd() + "`n" + $line + "`n"
    [System.IO.File]::WriteAllText((Join-Path (Get-Location) $bar), $c, $enc)
    Write-Host "  patched integration/index.ts export" -ForegroundColor DarkGray
  } else { Write-Host "  integration/index.ts already exports GmgnCliExecutor" -ForegroundColor DarkGray }
}

Write-Host ""; Write-Host "Verifying gate ..." -ForegroundColor Cyan
npx tsc --noEmit; if ($LASTEXITCODE -ne 0){ throw "typecheck failed" }
npx vitest run
Write-Host ""; Write-Host "Live GMGN executor installed." -ForegroundColor Green
Write-Host "Expected: 865 passed + 1 skipped." -ForegroundColor Yellow
